"""Build an isolated, editable Week 1 visual proposal; no curriculum edits."""
from pathlib import Path
import html,json
R=Path(__file__).resolve().parents[1];O=R/'outputs/week-01-graphics-review';A=O/'graphics';A.mkdir(parents=True,exist_ok=True)
e=lambda s:html.escape(str(s))
C={'ink':'#17384c','muted':'#476176','teal':'#086c68','purple':'#6541a5','orange':'#975014','blue':'#205fa1'}
def text(x,y,lines,size=22,color='ink',weight=500):
 if isinstance(lines,str):lines=[lines]
 return f'<text x="{x}" y="{y}" fill="{C.get(color,color)}" font-size="{size}" font-weight="{weight}">'+''.join(f'<tspan x="{x}" dy="{0 if i==0 else size*1.4}">{e(s)}</tspan>' for i,s in enumerate(lines))+'</text>'
def rect(x,y,w,h,fill='#fff',stroke='#cbdce5',rx=22):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def line(x,y,xx,yy,color='#7892a4',arrow=False,dashed=False):return f'<path d="M{x} {y} L{xx} {yy}" fill="none" stroke="{color}" stroke-width="3"'+(' marker-end="url(#arrow)"' if arrow else '')+(' stroke-dasharray="7 7"' if dashed else '')+'/>'
def pill(x,y,label,color='teal',width=155):return rect(x,y,width,34,'#fff',C[color],17)+text(x+14,y+24,label,15,color,750)
def icon(kind,x,y,scale=1):
 head=f'<g transform="translate({x} {y}) scale({scale})" fill="none" stroke="#17384c" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">'
 shapes={
 'bus':'<rect x="4" y="18" width="128" height="65" rx="13" fill="#f4c55c"/><path d="M14 34h100v26H14z" fill="#d8eff7"/><path d="M46 34v26m34-26v26"/><circle cx="30" cy="84" r="12" fill="#17384c"/><circle cx="106" cy="84" r="12" fill="#17384c"/>',
 'person':'<circle cx="58" cy="24" r="18" fill="#f5cbae"/><path d="M25 105V78c0-35 66-35 66 0v27" fill="#bde4df"/><path d="M40 80v25m36-25v25"/>',
 'rule':'<rect x="12" y="7" width="100" height="103" rx="9" fill="#ede5fb"/><path d="M33 34h56M33 55h38M33 80l12 12 29-29"/>',
 'model':'<circle cx="20" cy="25" r="10" fill="#c5e8e2"/><circle cx="20" cy="85" r="10" fill="#c5e8e2"/><circle cx="65" cy="55" r="15" fill="#88c8bf"/><circle cx="110" cy="25" r="10" fill="#c5e8e2"/><circle cx="110" cy="85" r="10" fill="#c5e8e2"/><path d="M30 28l23 19m-23 35 23-19m27-15 20-18m-20 34 20 18"/>',
 'records':'<rect x="8" y="5" width="105" height="110" rx="10" fill="#e3effa"/><path d="M30 30h60m-60 25h60m-60 25h60m-42-50v65m23-65v65"/>',
 'umbrella':'<path d="M6 55a56 56 0 0 1 112 0Q102 40 90 55 76 40 62 55 48 40 34 55 20 40 6 55Z" fill="#9edbd2"/><path d="M62 55v48q0 21 18 12M62 0v6"/>',
 'vacuum':'<ellipse cx="63" cy="71" rx="56" ry="33" fill="#c9dce9"/><path d="M7 71v12c0 42 112 42 112 0V71" fill="#e5eff5"/><ellipse cx="63" cy="60" rx="19" ry="9" fill="#fff"/><path d="M35 85h20"/>',
 'eye':'<path d="M3 58Q63-6 123 58 63 122 3 58Z" fill="#e0f2ef"/><circle cx="63" cy="58" r="22" fill="#fff"/><circle cx="63" cy="58" r="8" fill="#17384c"/>',
 'search':'<circle cx="49" cy="47" r="35" fill="#e1effa"/><path d="M76 75l37 37" stroke-width="11"/><path d="M32 48h34m-17-17v34"/>',
 'controller':'<path d="M25 35h80q20 0 22 30l3 27q0 22-22 9L89 85H40l-20 16Q-2 114 2 91l4-27q3-29 19-29Z" fill="#e0f2ef"/><path d="M24 60h24M36 48v24"/><circle cx="94" cy="57" r="4"/><circle cx="110" cy="71" r="4"/>',
 'light':'<path d="M42 79C-3 38 20 2 62 2s64 38 22 77l-8 16H48Z" fill="#ffe9a6"/><path d="M48 104h28m-25 10h22"/>',
 'photos':'<rect x="9" y="7" width="105" height="96" rx="8" fill="#e3effa"/><path d="M17 90l31-38 25 25 16-21 17 34" fill="#9edbd2"/><circle cx="88" cy="29" r="10" fill="#f4c55c"/>'}
 return head+shapes[kind]+'</g>'
def svg(name,title,desc,body):
 content=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="720" viewBox="0 0 1200 720" role="img" aria-labelledby="title desc"><title id="title">{e(title)}</title><desc id="desc">{e(desc)}</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#7892a4"/></marker></defs><rect width="1200" height="720" rx="24" fill="#f4f8fb"/><g font-family="Arial, Helvetica, sans-serif">{text(38,47,'AI ACADEMY  /  LEVEL 1 · WEEK 1',15,'teal',750)}{text(38,94,title,34,'ink',750)}{body}</g></svg>'''
 (A/(name+'.svg')).write_text(content)
 return {'id':name,'title':title,'alt':desc}
items=[]
b=rect(38,130,535,440)+rect(627,130,535,440)+pill(62,152,'1  OBSERVE','blue',165)+pill(651,152,'2  INVESTIGATE','teal',192)
b+=icon('bus',72,223,1.4)+rect(292,241,250,112,'#17384c','#17384c',12)+text(310,280,'DELAY 12 MIN',23,'#ffb0b0',750)+text(310,316,'RED DISPLAY',20,'#fff',650)
b+=text(62,420,['“The display is red.”','“It shows a 12-minute delay.”'],26)+text(62,516,'These describe what we can see.',20,'muted')
b+=icon('records',653,228,1)+text(803,250,['ENGINEERING NOTE'],19,'teal',750)+text(803,290,['Past journeys fitted','the delay model.'],23)+text(651,420,['“The estimator uses a model','learned from examples.”'],26)+text(651,516,'This claim needs process evidence.',20,'muted')
b+=rect(38,594,1124,88,'#e2f1ed','#b5d8ce')+text(62,631,['A red number tells us the colour — not how the number was produced.','Ask: “What evidence shows how this decision was made?”'],22)
items.append(svg('01-observe-and-investigate','Seeing a result is not explaining it','A bus has a red display showing a 12-minute delay. That is an observation. A supplied engineering note says past journeys fitted the delay model; that is evidence about its mechanism.',b))
b=''
for x,num,kind,label,example,lines,color in [(38,1,'controller','HUMAN COMMAND','Remote-controlled car',['A person sends each','steering instruction.'],'teal'),(422,2,'light','WRITTEN RULE','Motion-triggered lamp',['A person wrote:','if motion, turn on.'],'purple'),(806,3,'photos','LEARNED MODEL','Trained photo sorter',['Fitted on labelled pictures;','predicts a new label.'],'blue')]:
 b+=rect(x,138,356,408)+pill(x+20,158,label,color,310)+icon(kind,x+107,216,1.05)+text(x+22,380,example,24,'ink',750)+text(x+22,426,lines,22)
b+=rect(38,572,1124,110,'#fff3df','#e8c995')+text(62,612,['A single product can combine all three.','AI also includes symbolic reasoning. A simple switch alone does not classify a whole product.'],22)
items.append(svg('02-three-mechanisms','Who or what makes this decision?','A remote-controlled car follows human commands, a motion lamp follows a written rule, and a trained photo sorter applies a learned model. A product can combine mechanisms. AI also includes symbolic reasoning.',b))
b=''
rows=[(148,'1  LEARNED ESTIMATE','Current route + traffic','Model fitted on past journeys','Estimated delay: 12 min','blue'),(296,'2  WRITTEN COLOUR RULE','Estimated delay: 12 min','Is the delay greater than 10?','Yes → red display','purple'),(444,'3  HUMAN OVERRIDE','Driver sees closure notice','Driver chooses a message','Display: ROUTE CLOSED','teal')]
for y,label,left,mid,right,color in rows:
 b+=rect(38,y,1124,128)+text(56,y+30,label,16,color,750)+text(56,y+79,left,21)+line(332,y+75,382,y+75,arrow=True)+text(403,y+79,mid,20)+line(765,y+75,813,y+75,arrow=True)+text(833,y+79,right,21,'ink',750)
b+=text(60,631,['Follow one decision at a time: estimating a number, choosing a colour, replacing a message.','A correct colour comparison does not prove that the estimated delay is accurate.'],23)
items.append(svg('03-bus-decision-map','One bus display. Three different decisions.','Three separate rows trace the bus estimate, display colour and driver override. The fitted model estimates 12 minutes; the written greater-than-10 rule makes the display red; the driver can choose ROUTE CLOSED.',b))
b=rect(38,139,1124,191,'#e9f2fb','#b8d1e7')+pill(62,157,'EARLIER: FIT THE MODEL','blue',270)+icon('records',78,202,.8)+text(218,242,['Earlier weather records','Examples used during fitting'],23)+line(565,250,663,250,arrow=True)+icon('model',699,199,.85)+text(851,245,['Fitted weather','model'],24,'ink',750)
b+=rect(38,358,1124,215,'#e6f4ef','#b2d6cb')+pill(62,376,'NOW: USE THE MODEL','teal',255)+text(65,476,['New weather','measurements'],23)+line(272,467,345,467,arrow=True)+icon('model',374,412,.8)+line(515,467,584,467,arrow=True)+text(607,459,'70%',54,'blue',750)+text(608,501,'rain forecast',21)+rect(877,411,258,131,'#fff','#b2d6cb',16)+text(898,461,['Prediction,','not an action.'],23,'teal',750)
b+=text(62,620,['Fit means adjust a model using examples. Using it to predict is a later step.','A 70% rain forecast is an estimate, not a promise that it will rain.'],23)
items.append(svg('04-fit-then-predict','Learn first. Predict later.','Earlier weather records are used to fit a model. Later, new measurements are passed to that fitted model to obtain a 70 percent rain forecast. It is an estimate, not a guarantee.',b))
b=rect(38,138,1124,87,'#e8f1fa','#bed2e4')+text(62,190,'SAME FITTED MODEL + SAME INPUT → SAME FORECAST: 70%',26,'blue',750)
for x,boundary,comparison,conclusion,color in [(38,60,'70 ≥ 60','TAKE ONE','teal'),(627,80,'70 < 80','Rule does not trigger','purple')]:
 b+=rect(x,252,535,315)+pill(x+24,274,f'BOUNDARY: {boundary}% OR MORE',color,310)+text(x+26,381,comparison,49,color,750)+rect(x+24,413,487,99,'#17384c','#17384c',13)+text(x+46,469,conclusion,29,'#fff',750)
b+=text(62,620,['Only the written display boundary changed. The model was not refitted.','At an exact boundary (60% with a 60% rule), “or more” includes equality.'],23)
items.append(svg('05-change-only-the-rule','Change the rule. Keep the forecast.','With a 70 percent rain forecast, a 60 percent-or-more rule displays TAKE ONE. An 80 percent-or-more rule does not trigger that message. Only the boundary changed; the fitted model and forecast did not.',b))
b=rect(38,139,363,400)+icon('vacuum',140,211,1.05)+text(65,394,'“Smart” robot vacuum',25,'ink',750)+text(65,440,['It moves and cleans.','How does it choose a route?','The description does not say.'],21)
b+=line(422,337,472,337,arrow=True)+rect(495,139,667,400)+pill(519,160,'ASK FOR MECHANISM EVIDENCE','teal',365)+text(520,244,['Person steering? → evidence of human control','Explicit route instructions? → evidence of rules','Model fitted on examples? → evidence of learning'],23)+text(520,388,['Several may be combined.','If evidence is missing, say:','“I need more information.”'],25,'ink',650)
b+=rect(38,568,1124,116,'#fff3df','#e8c995')+text(62,607,['PROJECT: Draw input → deciding step → output for your classroom sorter.','Label each deciding step: human / written rule / learned model / not yet known.','Then name the evidence for your label.'],21)
items.append(svg('06-evidence-and-project','“Not enough information” is a useful answer','An unspecified smart robot vacuum moves and cleans, but its route mechanism is unknown. Ask for evidence of human commands, written rules or model fitting, and allow combinations. Apply this reasoning to a classroom sorter.',b))
notes=[
 ('What did you actually see?', 'Cover the right panel. Ask for two observations, then one question about the hidden process. Reveal the engineering note and distinguish a fact about the mechanism from a claim about accuracy.', 'Notice the evidence; observation, output, mechanism and evidence'),
 ('Explain the deciding step.', 'Ask learners to mime the car controller, trace the lamp instruction, and name the photo sorter’s training evidence. Avoid teaching that every rule is non-AI or every moving machine is AI.', 'Compare the cases; command, written rule, fitted model'),
 ('Trace the number, colour and override separately.', 'Point to each row and ask which input is used. The 12-minute prediction is not the colour decision. The driver override is a separate human decision; do not invent a priority between rows beyond the supplied facts.', 'See how it works; input, process and output'),
 ('What happens before a new forecast?', 'Trace the earlier fitting phase first, then the later use phase. An estimate may be wrong. Do not interpret 70% as a guarantee or claim calibration from a single forecast.', 'Follow a worked example; fitting versus using a fitted model'),
 ('Predict before revealing the right card.', 'Cover the right-hand result. Keep the forecast fixed at 70 and change only the boundary. Test 60 with a 60-or-more boundary verbally to check equality. No alternate message is specified when the rule does not trigger.', 'Find and repair a mistake; test a changed condition'),
 ('Which evidence would change your answer?', 'Invite more than one plausible mechanism, then request documentation or a process demonstration. Use the sorter prompt for supported practice. Keep the greenhouse independent assessment and its teacher key separate.', 'Run the investigation; project evidence and justified uncertainty')]
sections=[]
for i,(item,note) in enumerate(zip(items,notes),1):
 q,teacher,placement=note
 sections.append(f'''<section class="visual" id="graphic-{i}"><div class="section-top"><span>GRAPHIC {i:02}</span><span>{e(placement)}</span></div><h2>{e(item['title'])}</h2><a class="art" href="graphics/{item['id']}.svg" aria-label="Open full-size graphic: {e(item['title'])}"><img src="graphics/{item['id']}.svg" alt="{e(item['alt'])}" width="1200" height="720"></a><div class="explanation"><p>{e(item['alt'])}</p><p class="question">Pause &amp; explain: {e(q)}</p></div><details class="teacher"><summary>Teacher guidance</summary><p>{e(teacher)}</p></details><div class="downloads"><a href="graphics/{item['id']}.svg">Editable SVG</a><a href="graphics/{item['id']}.png">High-resolution PNG</a></div></section>''')
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#edf3f7;color:#17384c;font:18px/1.65 Arial,Helvetica,sans-serif}main{max-width:1280px;margin:auto;padding:30px}a{color:#155b88;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #975014;outline-offset:5px}header{padding:48px;background:#143e50;color:white;border-radius:24px}header p{max-width:780px;color:#e1eff5}h1{font-size:clamp(36px,5vw,64px);line-height:1.1;margin:20px 0}h2{font-size:30px;line-height:1.25}.eyebrow{font-size:14px;font-weight:750;letter-spacing:.12em}.intro{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:24px 0}.intro>div{background:white;border:1px solid #c4d6e1;padding:24px;border-radius:16px}.intro h2{font-size:23px;margin-top:0}nav{display:flex;flex-wrap:wrap;gap:12px;margin:26px 0}nav a,.downloads a,.pdf{padding:10px 16px;min-height:44px;border:1px solid #9eb8c8;border-radius:8px;background:white;text-decoration:none;font-weight:650}.visual{background:white;border:1px solid #c4d6e1;padding:28px;border-radius:20px;margin:30px 0;scroll-margin-top:16px}.section-top{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;font-size:13px;font-weight:750;color:#476176}.art{display:block;background:#f4f8fb;border:1px solid #d7e4ec;border-radius:16px;overflow:auto}.art img{display:block;width:100%;height:auto;min-width:720px}.explanation{max-width:1000px}.question{padding:16px 20px;background:#e8f5ef;border-left:5px solid #086c68;font-weight:650}summary{cursor:pointer;padding:14px 0;font-weight:700;min-height:44px}.teacher{border-top:1px solid #ccdce6}.teacher p{max-width:980px;margin-top:0}.downloads{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}.note{padding:24px;background:#fff2dc;border-radius:14px}footer{padding:30px 0;color:#476176}@media(max-width:700px){main{padding:14px}header{padding:26px}.intro{grid-template-columns:1fr}.visual{padding:16px}h2{font-size:25px}.art:after{content:'Swipe to explore the full diagram, or open it full size.';display:block;font-size:13px;padding:12px;position:sticky;left:0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{@page{size:A4 landscape;margin:12mm}body{font-size:11pt;background:white}main{padding:0;max-width:none}header{background:white;color:#17384c;padding:0}header p{color:#17384c}h1{font-size:36pt}nav,.downloads,.pdf,.intro,.note,footer{display:none}.visual{break-before:page;border:0;padding:0;margin:0}.art{overflow:visible;border:0}.art img{min-width:0;width:100%;max-height:140mm}.teacher{display:none}h2{font-size:18pt;margin:8px 0}.section-top{font-size:9pt}.explanation{font-size:10pt}.explanation p{margin:8px 0}.question{padding:8px}.art:after{display:none}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week 1 — AI or Not? · Graphics review</title><style>{style}</style></head><body><main id="main"><header><div class="eyebrow">AI ACADEMY · LEVEL 1 · WEEK 1 · VISUAL REVIEW</div><h1>AI or Not?<br>Follow the decision.</h1><p>Six concept graphics for a clearer first lesson. Start with what you can see. Find evidence of the deciding process. Explain what you still do not know.</p></header><div class="intro"><div><h2>For students</h2><p>Read each picture from left to right. Follow arrows, use labels and answer the green question. Colour helps you navigate; the words also identify every mechanism.</p></div><div><h2>For teachers</h2><p>Use one graphic at a time beside the matching lesson section. Open Teacher guidance for prompts and misconceptions. These are supported teaching examples; independent assessment remains separate.</p></div></div><p><a class="pdf" href="week-01-graphics-review.pdf">Download the printable visual booklet</a></p><nav aria-label="Concept graphics">{''.join(f'<a href="#graphic-{i}">{i:02} · {e(label)}</a>' for i,label in enumerate(['Observe','Mechanisms','Bus system','Fit → predict','Change a rule','Investigate'],1))}</nav><p class="note"><strong>Review draft.</strong> This proposal covers Level 1, Week 1 only. Existing lessons and other weeks have not been changed. Each graphic includes a text explanation and editable source.</p>{''.join(sections)}<footer>Based on the supplied Week 1 bus, umbrella and device cases. All diagrams are fictional teaching examples. Prepared for review before rollout.</footer></main></body></html>'''
(O/'index.html').write_text(page)
(O/'review-manifest.json').write_text(json.dumps({'week':'ai-1/1','status':'awaiting user review','graphics':items,'independent_assessment_answers_included':False},indent=2))
print('Prepared six concept graphics and review page:',O/'index.html')
